-- Alcaz Prison (map 2994): live's creatures and objects where live has them (114 creatures, 27 objects), live's factions and the
-- bosses' lines, in place of our hand-placed layout (2026_11_14_41, 2026_11_22_77 and the route kits after them). Runs after 2026_11_26_43.
-- Source: a live capture made on 26 November 2026 (client 1.60.1.71139) of a full clear, 21:59-22:13 (Overseer Wrex, Katerina the
-- Cleaner, Blazeroar, then The Questioner). Positions are where each creature and object was first seen, all from the landing at
-- 21:59:00-01, before anything was pulled.
-- Bosses at live's spots: Overseer Wrex (-8885.8, 2921.3), The Questioner (-8773.0, 2854.2) (ours had these two roughly swapped),
-- Katerina the Cleaner (-8808.5, 2971.1) with Commander Folkar beside her (-8808.5, 2979.1), Blazeroar (-8901.2, 2971.5).
-- Tidemistress Ca'zass is NOT spawned: live never showed her (her template and the instance's boss slot stay).
-- Each Renegade Conjurer has its Servitor beside it on live from the start (the Servitor is the Conjurer's summon); here the Servitor
-- stands there as a spawn (INFERRED: what makes live summon it is not in the capture).
-- Not taken: the player's own totems; live's paths (the run pulled most packs, so the paths are chases). Every creature stands
-- (MovementType 0). Respawn: bosses 1 day, the rest 2 hours.
-- Objects: the client's own query answers for the 26 templates we lacked (Prison Gates, the Maximum Security Door, Cell Doors, the
-- Alcaz Island Instance Portal, Binding Chain, Ball and chain, Perfumed Note), each in live's state (most doors closed; cell doors
-- 650870, 650871 and 650873 open). Prison Gate 649546 is not spawned: the player used it at 22:02:01 but its object was never sent
-- in a form the parser read, so its spot is not in the capture. No door scripts: a closed door stays closed until a player uses it.
-- Factions as live has them (live's FactionTemplate ids): Defias, Jailers, Chaplains, Conjurers, Servitors, Wrex, Katerina and
-- The Questioner 17; Strashaz 74; Slavering Hounds and Blazeroar stay 16; Commander Folkar 1074 (his unit flags keep him out of
-- reach, unchanged). Prisoners are 35 since 2026_11_26_43.
-- Lines: live's creature_text with live's broadcast texts. Our Alcaz script does not call them yet; when each is said on live is
-- in the comment of each row.
-- Removed with our spawns: their creature_addon rows, formations, paths (PathId = guid*10 and any path an addon names) and
-- per-spawn SmartAI. Creature guids 48150000-48150113, object guids 48150000-48150026. Safe to run again.
DROP TEMPORARY TABLE IF EXISTS `tmp_alcaz_old`;
CREATE TEMPORARY TABLE `tmp_alcaz_old` (`guid` BIGINT UNSIGNED PRIMARY KEY) SELECT `guid` FROM `creature` WHERE `map` = 2994;
DELETE n FROM `waypoint_path_node` n JOIN `creature_addon` a ON a.`PathId` = n.`PathId` JOIN `tmp_alcaz_old` t ON t.`guid` = a.`guid` WHERE a.`PathId` <> 0;
DELETE p FROM `waypoint_path` p JOIN `creature_addon` a ON a.`PathId` = p.`PathId` JOIN `tmp_alcaz_old` t ON t.`guid` = a.`guid` WHERE a.`PathId` <> 0;
DELETE FROM `waypoint_path_node` WHERE `PathId` BETWEEN 481200000 AND 481201999;
DELETE FROM `waypoint_path` WHERE `PathId` BETWEEN 481200000 AND 481201999;
DELETE f FROM `creature_formations` f JOIN `tmp_alcaz_old` t ON t.`guid` = f.`leaderGUID` OR t.`guid` = f.`memberGUID`;
DELETE s FROM `smart_scripts` s JOIN `tmp_alcaz_old` t ON s.`entryorguid` = -CAST(t.`guid` AS SIGNED) WHERE s.`source_type` = 0;
DELETE a FROM `creature_addon` a JOIN `tmp_alcaz_old` t ON t.`guid` = a.`guid`;
DELETE c FROM `creature` c JOIN `tmp_alcaz_old` t ON t.`guid` = c.`guid`;
DROP TEMPORARY TABLE `tmp_alcaz_old`;
DELETE FROM `creature` WHERE `guid` BETWEEN 48150000 AND 48150999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 48150000 AND 48150999;
DELETE ga FROM `gameobject_addon` ga JOIN `gameobject` g ON g.`guid` = ga.`guid` WHERE g.`map` = 2994;
DELETE FROM `gameobject` WHERE `map` = 2994;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 48150000 AND 48150999;
DELETE FROM `gameobject_addon` WHERE `guid` BETWEEN 48150000 AND 48150999;
DELETE FROM `gameobject_template` WHERE `entry` IN (617475,630604,639603,649547,649548,649549,649550,649551,649552,650867,650869,650870,650871,650872,650873,650874,650875,650876,650877,650878,650879,650880,650881,650882,651861,652329);
